#include <iostream>
using namespace std;

int main() {
    int a, b;
    cin >> a >> b;

    // 比较表达式的结果类型就是 bool，直接存起来即可
    bool greater = a > b;
    bool equal = (a == b);
    bool less = a < b;

    // 关键：cout 默认把 bool 当整数输出，true 打印成 1、false 打印成 0，
    // 而不是 true / false。想打印单词要加流操纵符 boolalpha。
    cout << greater << endl;
    cout << equal << endl;
    cout << less << endl;
    return 0;
}

