#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    // 花括号初始化：int a{}; 一定会把 a 初始化成 0。
    // 对比 C 风格的 int a; —— 局部变量不初始化就是内存里的随机值。
    int a{}, b{};
    cin >> a >> b;

    // auto 让编译器从等号右边推导类型：a + b 是 int，所以 sum 就是 int
    auto sum = a + b;

    // 关键：a + b 是整数，直接除以 2 会做整数除法（7 / 2 得到 3）。
    // 写成 2.0 之后整个表达式变成 double 运算，结果才是 3.5。
    auto avg = (a + b) / 2.0;

    cout << sum << endl;
    cout << fixed << setprecision(2) << avg << endl;
    return 0;
}

