#include <iostream>
using namespace std;

int main() {
    // cin >> c 会自动跳过空白字符，所以输入末尾的回车不会被当成字符读进来
    char c;
    cin >> c;

    // char 本质上是 1 字节的小整数。cout 默认按「字符」打印它，
    // 想看数字就必须显式转换。C++ 推荐 static_cast 而不是 C 的 (int) 写法：
    // 它更显眼、更容易搜索，也不会被误读成别的转换。
    cout << static_cast<int>(c) << endl;

    // 'a' 是 97、'A' 是 65，正好相差 32。
    // 写成 ('a' - 'A') 比写死 32 更能说明意图。
    // 注意 c - (...) 的结果是 int，要打印成字符得再转回 char。
    cout << static_cast<char>(c - ('a' - 'A')) << endl;
    return 0;
}

#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    double x;
    cin >> x;

    // static_cast<int>(x) 是 C++ 推荐的显式转换写法，效果和 C 的 (int)x 一样，
    // 但写成 static_cast 之后在代码里搜「类型转换」一搜就能找到。
    // 规则是「向 0 截断」：3.9 得 3，-2.7 得 -2，都不四舍五入。
    int whole = static_cast<int>(x);

    cout << whole << endl;

    // x - whole：int 会被隐式提升成 double，相减结果仍是小数，不会算错
    cout << fixed << setprecision(2) << (x - whole) << endl;
    return 0;
}

