#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    // 坑：如果写成 long long r = n * 2;，等号右边是先按 int 算完再赋值的。
    // n = 2147483647 时这个乘法已经在 int 里溢出了，而有符号整数溢出是
    // 「未定义行为」——结果不可预测，并不是简单地在某个数上绕回。
    //
    // 加上 LL 后缀（long long 字面量）之后，n 会先被提升成 long long，
    // 整个乘法在 64 位里完成，结果才是对的。
    long long r = n * 2LL;

    cout << r << endl;
    return 0;
}

