#include <iostream>
#include <iomanip>
using namespace std;

// const 定义的是真正的常量：有类型、有作用域，编译器会做类型检查。
// 它比 #define PI 3.14159 安全——#define 只是编译前的文本替换，
// 没有类型，也不会被编译器检查。
const double PI = 3.14159;

int main() {
    int r;
    cin >> r;

    // 2 * PI * r：PI 是 double，所以 r 会被隐式提升成 double，整条表达式按小数算。
    // 如果把 PI 写成整数 3，全程就变成整数运算，周长会算成一个整数。
    double circumference = 2 * PI * r;
    double area = PI * r * r;

    // fixed + setprecision(2) 一旦设置就持续生效，后面所有浮点输出都保留 2 位小数
    cout << fixed << setprecision(2);
    cout << circumference << endl;
    cout << area << endl;
    return 0;
}

